N1 = 100001
divisors = [[] for d in range(N1)]
lpf = [0] * N1
for d in range(2, N1):
	if lpf[d]:
		for n in range(d, N1, d):
			divisors[n].append(d)
	else:
		for n in range(d, N1, d):
			lpf[n] = d
			divisors[n].append(d)
disp = [0, 0]
for n in range(2, N1):
	disp.append(disp[n // lpf[n]] + (n % (lpf[n] * lpf[n]) != 0))
from collections import defaultdict
for _ in range(int(input())):
	n = int(input())
	d = defaultdict(int)
	for s in input().split():
		for i in divisors[int(s)]:
			d[i] += 1
	ans = 0
	for i in d:
		x = disp[i] * d[i]
		if x > ans:
			ans = x
	print(ans)
